/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const vm = require('vm');
const assert = require('assert');
const html = fs.readFileSync('index.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
new vm.Script(script);
const elements = {};
function element(id) {
  return elements[id] ||= { value: '', disabled: false, listeners: {}, classList: { values: new Set(), add(v) { this.values.add(v); }, remove(v) { this.values.delete(v); }, toggle(v, on) { on ? this.add(v) : this.remove(v); }, contains(v) { return this.values.has(v); } }, addEventListener(type, handler) { this.listeners[type] = handler; }, focus() {}, setCustomValidity(value) { this.validityMessage = value; }, reportValidity() {}, stepUp() { this.value = String(Number(this.value) + 1); }, stepDown() { this.value = String(Number(this.value) - 1); } };
}
const form = element('rsvp-form');
form.elements = { attending: { value: 'yes' } };
const radios = [element('yes'), element('no')];
form.querySelectorAll = () => radios;
element('guest-count').value = '1';
const storage = {};
vm.runInNewContext(script, { document: { getElementById: element, querySelector: element }, localStorage: { getItem: key => storage[key] || null, setItem: (key, value) => storage[key] = value } });
assert(element('decrease').disabled);
element('increase').listeners.click();
assert.equal(element('guest-count').value, '2');
assert("'!element('"'decrease').disabled);
form.elements.attending.value = 'no';
radios[1].listeners.change();
assert(element('guest-count').disabled);
assert(element('dietary').disabled);
element('guest-name').value = 'Alex Taylor';
form.listeners.submit({ preventDefault() {} });
const saved = JSON.parse(storage['sam-priya-wedding-rsvp']);
assert.equal(saved.guests, 0);
assert.equal(saved.name, 'Alex Taylor');
assert(form.classList.contains('hidden'));
assert("'!element('"'confirmation').classList.contains('hidden'));
element('edit-response').listeners.click();
assert("'!form.classList.contains('"'hidden'));
form.elements.attending.value = 'yes';
radios[0].listeners.change();
element('dietary').value = 'Vegetarian';
form.listeners.submit({ preventDefault() {} });
assert.equal(JSON.parse(storage['sam-priya-wedding-rsvp']).guests, 2);
assert.equal(JSON.parse(storage['sam-priya-wedding-rsvp']).dietary, 'Vegetarian');
const ids = [...html.matchAll(/\\bid=\"(["'^"]+)"/g)].map(match => match[1]);
assert.equal(ids.length, new Set(ids).size);
console.log('"'Passed: JavaScript syntax, guest controls, attendance changes, saved responses, confirmation, editing, and unique HTML IDs.');
NODE"

